(333, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 240, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":240,\"component_id\":10,\"name\":\"title\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Elevating Standards in Vertical Transportation\",\"group\":\"2\",\"schema_group\":1,\"schema_instance\":1,\"position\":1,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-03-13T06:10:34.000000Z\",\"updated_at\":\"2026-03-13T06:10:34.000000Z\"}}', NULL, '2026-03-13 06:10:34', '2026-03-13 06:10:34'),
(334, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 241, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":241,\"component_id\":10,\"name\":\"desc1\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"RAR Lift is a premier vendor and distributor of international lift brands in Bangladesh. We specialize in the supply, installation, testing, commissioning, and maintenance of all types of elevators, escalators, and moving walks.\",\"group\":\"2\",\"schema_group\":1,\"schema_instance\":1,\"position\":2,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-03-13T06:10:34.000000Z\",\"updated_at\":\"2026-03-13T06:10:34.000000Z\"}}', NULL, '2026-03-13 06:10:34', '2026-03-13 06:10:34'),
(335, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 242, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":242,\"component_id\":10,\"name\":\"desc2\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Our mission is to provide seamless, safe, and sophisticated vertical mobility solutions that enhance the architectural value of modern buildings while ensuring absolute passenger comfort.\",\"group\":\"2\",\"schema_group\":1,\"schema_instance\":1,\"position\":3,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-03-13T06:10:34.000000Z\",\"updated_at\":\"2026-03-13T06:10:34.000000Z\"}}', NULL, '2026-03-13 06:10:34', '2026-03-13 06:10:34'),
(336, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 243, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":243,\"component_id\":10,\"name\":\"quote\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"A lift is considered the heart of a building. Urban life stands still if the lift does not provide uninterrupted services. At RAR Lift, we bring customized, reliable solutions for your lifestyle.\",\"group\":\"2\",\"schema_group\":1,\"schema_instance\":1,\"position\":4,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-03-13T06:10:34.000000Z\",\"updated_at\":\"2026-03-13T06:10:34.000000Z\"}}', NULL, '2026-03-13 06:10:34', '2026-03-13 06:10:34'),
