(685, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 437, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":437,\"component_id\":19,\"name\":\"elevators\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"6 Units\",\"group\":\"2\",\"schema_group\":1,\"schema_instance\":1,\"position\":3,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-03-14T08:48:50.000000Z\",\"updated_at\":\"2026-03-14T08:48:50.000000Z\"}}', NULL, '2026-03-14 08:48:50', '2026-03-14 08:48:50'),
(686, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 438, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":438,\"component_id\":19,\"name\":\"completion_year\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Completed 2023\",\"group\":\"2\",\"schema_group\":1,\"schema_instance\":1,\"position\":4,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-03-14T08:48:50.000000Z\",\"updated_at\":\"2026-03-14T08:48:50.000000Z\"}}', NULL, '2026-03-14 08:48:50', '2026-03-14 08:48:50'),
(687, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 439, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":439,\"component_id\":19,\"name\":\"details\",\"type\":\"textEditor\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"<p><br><\\/p><h3 style=\\\"line-height: 2rem\\\">Project Overview<\\/h3><p>The City Center Tower is a landmark commercial building in the heart of Dhaka. RAR Lift was chosen to provide a comprehensive vertical mobility solution that could handle high traffic volumes while maintaining energy efficiency and passenger comfort.<\\/p><h3 style=\\\"line-height: 2rem\\\">The Challenge<\\/h3><p>The primary challenge was installing high-speed elevators in a tightly constrained shaft space while minimizing disruption to the ongoing construction of the surrounding floors.<\\/p><h3 style=\\\"line-height: 2rem\\\">Our Solution<\\/h3><p>We installed 6 KOYO high-speed passenger elevators featuring advanced destination dispatch systems. This reduced wait times by 30% and optimized traffic flow during peak hours<\\/p>\",\"group\":\"2\",\"schema_group\":1,\"schema_instance\":1,\"position\":5,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-03-14T08:48:50.000000Z\",\"updated_at\":\"2026-03-14T08:48:50.000000Z\"}}', NULL, '2026-03-14 08:48:50', '2026-03-14 08:48:50'),
