(4955, 'componentfield', 'updated', 'App\\Models\\ComponentField', 'updated', 2469, 'App\\Models\\User', 1, '{\"attributes\":{\"value\":\"Safe, Reliable & Modern Elevator Solutions for Every Building\",\"updated_at\":\"2026-05-20T11:33:01.000000Z\"},\"old\":{\"value\":\"Architecture in motion.\",\"updated_at\":\"2026-05-20T06:09:50.000000Z\"}}', NULL, '2026-05-20 11:33:01', '2026-05-20 11:33:01'),
(4956, 'componentfield', 'updated', 'App\\Models\\ComponentField', 'updated', 2473, 'App\\Models\\User', 1, '{\"attributes\":{\"value\":\"RARlift provides professional elevator and escalator supply, installation, testing, commissioning, and maintenance services across Bangladesh. We deliver safe, durable, and modern vertical transportation solutions for residential, commercial, industrial, and institutional buildings.\",\"updated_at\":\"2026-05-20T11:33:01.000000Z\"},\"old\":{\"value\":\"We engineer elevators that move people seamlessly through the world\'s finest architectural achievements, blending invisible performance with striking design.\",\"updated_at\":\"2026-05-20T06:09:50.000000Z\"}}', NULL, '2026-05-20 11:33:01', '2026-05-20 11:33:01');
