(4957, 'componentfield', 'updated', 'App\\Models\\ComponentField', 'updated', 2474, 'App\\Models\\User', 1, '{\"attributes\":{\"value\":\"products\",\"updated_at\":\"2026-05-20T11:33:01.000000Z\"},\"old\":{\"value\":\"contact\",\"updated_at\":\"2026-05-20T06:09:50.000000Z\"}}', NULL, '2026-05-20 11:33:01', '2026-05-20 11:33:01'),
(4958, 'componentfield', 'updated', 'App\\Models\\ComponentField', 'updated', 2475, 'App\\Models\\User', 1, '{\"attributes\":{\"value\":\"Explore Our Products\",\"updated_at\":\"2026-05-20T11:33:01.000000Z\"},\"old\":{\"value\":\"Request a quote\",\"updated_at\":\"2026-05-20T06:09:50.000000Z\"}}', NULL, '2026-05-20 11:33:01', '2026-05-20 11:33:01'),
(4959, 'componentfield', 'updated', 'App\\Models\\ComponentField', 'updated', 241, 'App\\Models\\User', 1, '{\"attributes\":{\"value\":\"RARlift is a professional lift and elevator supply and service company in Bangladesh, dedicated to delivering safe, efficient, and long-lasting vertical mobility solutions. From product selection to installation and after-sales service, we support clients at every stage of their project.\",\"updated_at\":\"2026-05-20T12:07:13.000000Z\"},\"old\":{\"value\":\"RAR Lift is a premier vendor and distributor of international lift brands in Bangladesh. We specialize in the supply, installation, testing, commissioning, and maintenance of all types of elevators, escalators, and moving walks.\",\"updated_at\":\"2026-03-13T06:10:34.000000Z\"}}', NULL, '2026-05-20 12:07:14', '2026-05-20 12:07:14'),
(4960, 'componentfield', 'updated', 'App\\Models\\ComponentField', 'updated', 242, 'App\\Models\\User', 1, '{\"attributes\":{\"value\":\"We work with trusted international elevator brands and experienced technical teams to ensure each lift is installed with precision, tested properly, and maintained for reliable day-to-day performance.\",\"updated_at\":\"2026-05-20T12:07:14.000000Z\"},\"old\":{\"value\":\"Our mission is to provide seamless, safe, and sophisticated vertical mobility solutions that enhance the architectural value of modern buildings while ensuring absolute passenger comfort.\",\"updated_at\":\"2026-03-13T06:10:34.000000Z\"}}', NULL, '2026-05-20 12:07:14', '2026-05-20 12:07:14'),
(4961, 'componentfield', 'updated', 'App\\Models\\ComponentField', 'updated', 243, 'App\\Models\\User', 1, '{\"attributes\":{\"value\":\"A lift is the heart of a modern building. At RARlift, our mission is to provide safe, reliable, and comfortable elevator solutions that improve everyday movement and enhance the value of every building\",\"updated_at\":\"2026-05-20T12:07:14.000000Z\"},\"old\":{\"value\":\"A lift is considered the heart of a building. Urban life stands still if the lift does not provide uninterrupted services. At RAR Lift, we bring customized, reliable solutions for your lifestyle.\",\"updated_at\":\"2026-03-13T06:10:34.000000Z\"}}', NULL, '2026-05-20 12:07:14', '2026-05-20 12:07:14'),
(4962, 'componentfield', 'updated', 'App\\Models\\ComponentField', 'updated', 247, 'App\\Models\\User', 1, '{\"attributes\":{\"value\":\"Every installation follows proper safety procedures, technical standards, and quality checks.\",\"updated_at\":\"2026-05-20T12:07:14.000000Z\"},\"old\":{\"value\":\"Uncompromising safety standards in every installation.\",\"updated_at\":\"2026-04-08T11:12:59.000000Z\"}}', NULL, '2026-05-20 12:07:14', '2026-05-20 12:07:14'),
(4963, 'componentfield', 'updated', 'App\\Models\\ComponentField', 'updated', 249, 'App\\Models\\User', 1, '{\"attributes\":{\"value\":\"Quality Products\",\"updated_at\":\"2026-05-20T12:07:14.000000Z\"},\"old\":{\"value\":\"Premium Quality\",\"updated_at\":\"2026-04-08T11:13:00.000000Z\"}}', NULL, '2026-05-20 12:07:14', '2026-05-20 12:07:14'),
(4964, 'componentfield', 'updated', 'App\\Models\\ComponentField', 'updated', 250, 'App\\Models\\User', 1, '{\"attributes\":{\"value\":\"We supply reliable elevator systems from trusted global manufacturing partners.\",\"updated_at\":\"2026-05-20T12:07:14.000000Z\"},\"old\":{\"value\":\"Partnering only with globally recognized lift brands.\",\"updated_at\":\"2026-04-08T11:13:00.000000Z\"}}', NULL, '2026-05-20 12:07:14', '2026-05-20 12:07:14'),
(4965, 'componentfield', 'updated', 'App\\Models\\ComponentField', 'updated', 252, 'App\\Models\\User', 1, '{\"attributes\":{\"value\":\"Expert Installation\",\"updated_at\":\"2026-05-20T12:07:14.000000Z\"},\"old\":{\"value\":\"Reliability\",\"updated_at\":\"2026-04-08T11:13:00.000000Z\"}}', NULL, '2026-05-20 12:07:14', '2026-05-20 12:07:14'),
