(4993, 'componentfield', 'updated', 'App\\Models\\ComponentField', 'updated', 284, 'App\\Models\\User', 1, '{\"attributes\":{\"value\":\"lifttrade2007@gmail.com\",\"updated_at\":\"2026-05-20T18:31:32.000000Z\"},\"old\":{\"value\":\"info@rarlift.com\",\"updated_at\":\"2026-03-13T00:34:01.000000Z\"}}', NULL, '2026-05-21 00:31:32', '2026-05-21 00:31:32'),
(4994, 'componentfield', 'updated', 'App\\Models\\ComponentField', 'updated', 2196, 'App\\Models\\User', 1, '{\"attributes\":{\"value\":\"A lift is more than a machine for moving people between floors. It is an essential part of modern urban life, building convenience, and daily comfort. When a lift performs smoothly, people move confidently. When it stops, the entire building experience is affected.\",\"updated_at\":\"2026-05-20T18:35:30.000000Z\"},\"old\":{\"value\":\"Lift is no longer just a means of going up and down. It has blended with urban lifestyle. Modern buildings are designed with lots of emotion mixed with our culture and heritage.\",\"updated_at\":\"2026-04-18T09:25:30.000000Z\"}}', NULL, '2026-05-21 00:35:30', '2026-05-21 00:35:30'),
(4995, 'componentfield', 'updated', 'App\\Models\\ComponentField', 'updated', 2197, 'App\\Models\\User', 1, '{\"attributes\":{\"value\":\"At RARlift, we understand the importance of safe and uninterrupted elevator service. That is why we are committed to providing reliable lift solutions that combine quality products, professional installation, and responsive after-sales support.\",\"updated_at\":\"2026-05-20T18:35:30.000000Z\"},\"old\":{\"value\":\"A lift is considered as a heart of a building. Urban life stands still if the lift does not provide uninterrupted services. Thus lift business is stepping into the next level in order to keep pace with modern lifestyle.\",\"updated_at\":\"2026-04-18T09:25:30.000000Z\"}}', NULL, '2026-05-21 00:35:30', '2026-05-21 00:35:30'),
(4996, 'componentfield', 'updated', 'App\\Models\\ComponentField', 'updated', 2198, 'App\\Models\\User', 1, '{\"attributes\":{\"value\":\"Our team works closely with clients to understand their building requirements and recommend the most suitable elevator solution. From residential apartments to commercial and institutional projects, we aim to deliver systems that are safe, comfortable, and built for long-term performance.\",\"updated_at\":\"2026-05-20T18:35:30.000000Z\"},\"old\":{\"value\":\"Our commitment to quality and safety is unwavering. We partner with the world\'s leading brands to ensure that every installation meets the highest international standards. Our team of dedicated professionals works tirelessly to provide seamless service from consultation to after-sales support.\",\"updated_at\":\"2026-04-18T09:25:30.000000Z\"}}', NULL, '2026-05-21 00:35:30', '2026-05-21 00:35:30'),
(4997, 'componentfield', 'updated', 'App\\Models\\ComponentField', 'updated', 2199, 'App\\Models\\User', 1, '{\"attributes\":{\"value\":\"Thank you for trusting RARlift as your vertical mobility partner. We look forward to supporting your projects and helping your buildings move better.\",\"updated_at\":\"2026-05-20T18:35:30.000000Z\"},\"old\":{\"value\":\"Thank you for trusting RAR Lift as your vertical mobility partner. We look forward to elevating your projects to new heights.\",\"updated_at\":\"2026-04-18T09:25:30.000000Z\"}}', NULL, '2026-05-21 00:35:30', '2026-05-21 00:35:30'),
(4998, 'componentfield', 'updated', 'App\\Models\\ComponentField', 'updated', 2371, 'App\\Models\\User', 1, '{\"attributes\":{\"value\":\"ur Management Team\",\"updated_at\":\"2026-05-20T18:36:26.000000Z\"},\"old\":{\"value\":\"Our Leadership Team\",\"updated_at\":\"2026-05-02T00:50:11.000000Z\"}}', NULL, '2026-05-21 00:36:26', '2026-05-21 00:36:26'),
(4999, 'componentfield', 'updated', 'App\\Models\\ComponentField', 'updated', 2372, 'App\\Models\\User', 1, '{\"attributes\":{\"value\":\"RARlift is led by professionals with experience in elevator supply, project coordination, technical installation, and customer service. Our team works together to ensure every project is completed with safety, quality, and reliability.\",\"updated_at\":\"2026-05-20T18:36:26.000000Z\"},\"old\":{\"value\":\"The experts behind RAR Lift, dedicated to safety, innovation, and excellence in vertical transportation.\",\"updated_at\":\"2026-05-02T00:50:11.000000Z\"}}', NULL, '2026-05-21 00:36:26', '2026-05-21 00:36:26'),
(5000, 'componentfield', 'updated', 'App\\Models\\ComponentField', 'updated', 461, 'App\\Models\\User', 1, '{\"attributes\":{\"value\":\"Contact RARlift\",\"updated_at\":\"2026-05-20T18:37:53.000000Z\"},\"old\":{\"value\":\"Contact Us\",\"updated_at\":\"2026-03-14T21:25:37.000000Z\"}}', NULL, '2026-05-21 00:37:53', '2026-05-21 00:37:53'),
(5001, 'componentfield', 'updated', 'App\\Models\\ComponentField', 'updated', 462, 'App\\Models\\User', 1, '{\"attributes\":{\"value\":\"Need a new elevator, service support, or project quotation? Contact RARlift today. Our team is ready to help you choose the right lift solution for your building.\",\"updated_at\":\"2026-05-20T18:37:53.000000Z\"},\"old\":{\"value\":\"Have a question or need a quote? Reach out to our team of experts. We\'re here to help you with all your elevator needs.\",\"updated_at\":\"2026-03-14T21:25:37.000000Z\"}}', NULL, '2026-05-21 00:37:53', '2026-05-21 00:37:53'),
