(5618, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2674, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2674,\"component_id\":43,\"name\":\"Step Title\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Assessment\",\"group\":\"2\",\"schema_group\":8,\"schema_instance\":3,\"position\":26,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-06T09:11:46.000000Z\",\"updated_at\":\"2026-10-06T09:11:46.000000Z\"}}', NULL, '2026-10-06 09:11:46', '2026-10-06 09:11:46'),
(5619, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2675, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2675,\"component_id\":43,\"name\":\"Step Description\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Our consultants compare your position against destination requirements and identify gaps.\",\"group\":\"2\",\"schema_group\":8,\"schema_instance\":3,\"position\":27,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-06T09:11:46.000000Z\",\"updated_at\":\"2026-10-06T09:11:46.000000Z\"}}', NULL, '2026-10-06 09:11:46', '2026-10-06 09:11:46'),
(5620, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2676, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2676,\"component_id\":43,\"name\":\"Step Title\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Written report\",\"group\":\"2\",\"schema_group\":8,\"schema_instance\":4,\"position\":28,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-06T09:11:46.000000Z\",\"updated_at\":\"2026-10-06T09:11:46.000000Z\"}}', NULL, '2026-10-06 09:11:46', '2026-10-06 09:11:46'),
(5621, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2677, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2677,\"component_id\":43,\"name\":\"Step Description\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"You receive a written assessment with a prioritised plan and timeline.\",\"group\":\"2\",\"schema_group\":8,\"schema_instance\":4,\"position\":29,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-06T09:11:46.000000Z\",\"updated_at\":\"2026-10-06T09:11:46.000000Z\"}}', NULL, '2026-10-06 09:11:46', '2026-10-06 09:11:46'),
(5622, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2678, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2678,\"component_id\":43,\"name\":\"Step Title\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Follow-up review\",\"group\":\"2\",\"schema_group\":8,\"schema_instance\":5,\"position\":30,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-06T09:11:46.000000Z\",\"updated_at\":\"2026-10-06T09:11:46.000000Z\"}}', NULL, '2026-10-06 09:11:46', '2026-10-06 09:11:46'),
(5623, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2679, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2679,\"component_id\":43,\"name\":\"Step Description\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"We reassess once corrective steps have been taken and funds have matured.\",\"group\":\"2\",\"schema_group\":8,\"schema_instance\":5,\"position\":31,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-06T09:11:46.000000Z\",\"updated_at\":\"2026-10-06T09:11:46.000000Z\"}}', NULL, '2026-10-06 09:11:46', '2026-10-06 09:11:46'),
(5624, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2680, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2680,\"component_id\":43,\"name\":\"Section Title\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Frequently asked questions\",\"group\":\"2\",\"schema_group\":9,\"schema_instance\":1,\"position\":32,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-06T09:11:47.000000Z\",\"updated_at\":\"2026-10-06T09:11:47.000000Z\"}}', NULL, '2026-10-06 09:11:47', '2026-10-06 09:11:47'),
(5625, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2681, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2681,\"component_id\":43,\"name\":\"Question\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"How early should the assessment be done?\",\"group\":\"2\",\"schema_group\":10,\"schema_instance\":1,\"position\":33,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-06T09:11:47.000000Z\",\"updated_at\":\"2026-10-06T09:11:47.000000Z\"}}', NULL, '2026-10-06 09:11:47', '2026-10-06 09:11:47'),
(5626, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2682, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2682,\"component_id\":43,\"name\":\"Answer\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Ideally six to nine months before your intended intake. Fund maturity periods and transaction history cannot be created retrospectively, so early assessment gives you time to organise your position properly.\",\"group\":\"2\",\"schema_group\":10,\"schema_instance\":1,\"position\":34,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-06T09:11:47.000000Z\",\"updated_at\":\"2026-10-06T09:11:47.000000Z\"}}', NULL, '2026-10-06 09:11:47', '2026-10-06 09:11:47'),
(5627, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2683, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2683,\"component_id\":43,\"name\":\"Question\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Does the assessment guarantee a particular outcome?\",\"group\":\"2\",\"schema_group\":10,\"schema_instance\":2,\"position\":35,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-06T09:11:47.000000Z\",\"updated_at\":\"2026-10-06T09:11:47.000000Z\"}}', NULL, '2026-10-06 09:11:47', '2026-10-06 09:11:47'),
(5628, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2684, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2684,\"component_id\":43,\"name\":\"Answer\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"No. Visa decisions rest entirely with the relevant immigration authority. Our role is to help you prepare accurate, complete and well-organised financial documentation.\",\"group\":\"2\",\"schema_group\":10,\"schema_instance\":2,\"position\":36,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-06T09:11:47.000000Z\",\"updated_at\":\"2026-10-06T09:11:47.000000Z\"}}', NULL, '2026-10-06 09:11:47', '2026-10-06 09:11:47'),
(5629, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2685, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2685,\"component_id\":43,\"name\":\"Question\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Can you assess more than one sponsor?\",\"group\":\"2\",\"schema_group\":10,\"schema_instance\":3,\"position\":37,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-06T09:11:47.000000Z\",\"updated_at\":\"2026-10-06T09:11:47.000000Z\"}}', NULL, '2026-10-06 09:11:47', '2026-10-06 09:11:47'),
(5630, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2686, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2686,\"component_id\":43,\"name\":\"Answer\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Yes. Multiple sponsors are common. We review each sponsor separately and then assess the combined position and how the sponsorship should be structured and evidenced.\",\"group\":\"2\",\"schema_group\":10,\"schema_instance\":3,\"position\":38,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-06T09:11:47.000000Z\",\"updated_at\":\"2026-10-06T09:11:47.000000Z\"}}', NULL, '2026-10-06 09:11:47', '2026-10-06 09:11:47'),
