(5703, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2737, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2737,\"component_id\":43,\"name\":\"Step Description\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"We discuss your destination, intake and the financial position of the student and sponsors.\",\"group\":\"2\",\"schema_group\":9,\"schema_instance\":1,\"position\":24,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-06T09:47:57.000000Z\",\"updated_at\":\"2026-10-06T09:47:57.000000Z\"}}', NULL, '2026-10-06 09:47:57', '2026-10-06 09:47:57'),
(5704, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2738, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2738,\"component_id\":43,\"name\":\"Step Title\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Document collection \",\"group\":\"2\",\"schema_group\":9,\"schema_instance\":2,\"position\":25,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-06T09:47:58.000000Z\",\"updated_at\":\"2026-10-06T09:47:58.000000Z\"}}', NULL, '2026-10-06 09:47:58', '2026-10-06 09:47:58'),
(5705, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2739, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2739,\"component_id\":43,\"name\":\"Step Description\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"You share statements, income evidence and asset details through a structured checklist.\",\"group\":\"2\",\"schema_group\":9,\"schema_instance\":2,\"position\":26,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-06T09:47:58.000000Z\",\"updated_at\":\"2026-10-06T09:47:58.000000Z\"}}', NULL, '2026-10-06 09:47:58', '2026-10-06 09:47:58'),
(5706, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2740, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2740,\"component_id\":43,\"name\":\"Step Title\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Assessment \",\"group\":\"2\",\"schema_group\":9,\"schema_instance\":3,\"position\":27,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-06T09:47:58.000000Z\",\"updated_at\":\"2026-10-06T09:47:58.000000Z\"}}', NULL, '2026-10-06 09:47:58', '2026-10-06 09:47:58'),
(5707, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2741, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2741,\"component_id\":43,\"name\":\"Step Description\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Our consultants compare your position against destination requirements and identify gaps.  \",\"group\":\"2\",\"schema_group\":9,\"schema_instance\":3,\"position\":28,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-06T09:47:58.000000Z\",\"updated_at\":\"2026-10-06T09:47:58.000000Z\"}}', NULL, '2026-10-06 09:47:58', '2026-10-06 09:47:58'),
(5708, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2742, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2742,\"component_id\":43,\"name\":\"Step Title\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Written report \",\"group\":\"2\",\"schema_group\":9,\"schema_instance\":4,\"position\":29,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-06T09:47:58.000000Z\",\"updated_at\":\"2026-10-06T09:47:58.000000Z\"}}', NULL, '2026-10-06 09:47:58', '2026-10-06 09:47:58'),
(5709, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2743, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2743,\"component_id\":43,\"name\":\"Step Description\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"You receive a written assessment with a prioritised plan and timeline. \",\"group\":\"2\",\"schema_group\":9,\"schema_instance\":4,\"position\":30,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-06T09:47:58.000000Z\",\"updated_at\":\"2026-10-06T09:47:58.000000Z\"}}', NULL, '2026-10-06 09:47:58', '2026-10-06 09:47:58'),
(5710, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2744, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2744,\"component_id\":43,\"name\":\"Step Title\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\" Follow-up review \",\"group\":\"2\",\"schema_group\":9,\"schema_instance\":5,\"position\":31,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-06T09:47:58.000000Z\",\"updated_at\":\"2026-10-06T09:47:58.000000Z\"}}', NULL, '2026-10-06 09:47:58', '2026-10-06 09:47:58'),
(5711, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2745, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2745,\"component_id\":43,\"name\":\"Step Description\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"We reassess once corrective steps have been taken and funds have matured.\",\"group\":\"2\",\"schema_group\":9,\"schema_instance\":5,\"position\":32,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-06T09:47:58.000000Z\",\"updated_at\":\"2026-10-06T09:47:58.000000Z\"}}', NULL, '2026-10-06 09:47:58', '2026-10-06 09:47:58'),
(5712, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2746, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2746,\"component_id\":43,\"name\":\"Frequently Asked Questions Section Title\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Frequently asked questions\",\"group\":\"2\",\"schema_group\":10,\"schema_instance\":1,\"position\":33,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-06T09:47:59.000000Z\",\"updated_at\":\"2026-10-06T09:47:59.000000Z\"}}', NULL, '2026-10-06 09:47:59', '2026-10-06 09:47:59'),
(5713, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2747, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2747,\"component_id\":43,\"name\":\"Question\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"How early should the assessment be done?\",\"group\":\"2\",\"schema_group\":11,\"schema_instance\":1,\"position\":34,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-06T09:47:59.000000Z\",\"updated_at\":\"2026-10-06T09:47:59.000000Z\"}}', NULL, '2026-10-06 09:47:59', '2026-10-06 09:47:59'),
(5714, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2748, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2748,\"component_id\":43,\"name\":\"Answer\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Ideally six to nine months before your intended intake. Fund maturity periods and transaction history cannot be created retrospectively, so early assessment gives you time to organise your position properly.\",\"group\":\"2\",\"schema_group\":11,\"schema_instance\":1,\"position\":35,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-06T09:47:59.000000Z\",\"updated_at\":\"2026-10-06T09:47:59.000000Z\"}}', NULL, '2026-10-06 09:47:59', '2026-10-06 09:47:59'),
(5715, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2749, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2749,\"component_id\":43,\"name\":\"Question\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Does the assessment guarantee a particular outcome?\",\"group\":\"2\",\"schema_group\":11,\"schema_instance\":2,\"position\":36,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-06T09:47:59.000000Z\",\"updated_at\":\"2026-10-06T09:47:59.000000Z\"}}', NULL, '2026-10-06 09:47:59', '2026-10-06 09:47:59'),
(5716, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2750, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2750,\"component_id\":43,\"name\":\"Answer\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"No. Visa decisions rest entirely with the relevant immigration authority. Our role is to help you prepare accurate, complete and well-organised financial documentation.\",\"group\":\"2\",\"schema_group\":11,\"schema_instance\":2,\"position\":37,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-06T09:47:59.000000Z\",\"updated_at\":\"2026-10-06T09:47:59.000000Z\"}}', NULL, '2026-10-06 09:47:59', '2026-10-06 09:47:59'),
(5717, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2751, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2751,\"component_id\":43,\"name\":\"Question\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Can you assess more than one sponsor?\",\"group\":\"2\",\"schema_group\":11,\"schema_instance\":3,\"position\":38,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-06T09:47:59.000000Z\",\"updated_at\":\"2026-10-06T09:47:59.000000Z\"}}', NULL, '2026-10-06 09:47:59', '2026-10-06 09:47:59'),
(5718, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2752, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2752,\"component_id\":43,\"name\":\"Answer\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Yes. Multiple sponsors are common. We review each sponsor separately and then assess the combined position and how the sponsorship should be structured and evidenced.\",\"group\":\"2\",\"schema_group\":11,\"schema_instance\":3,\"position\":39,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-06T09:47:59.000000Z\",\"updated_at\":\"2026-10-06T09:47:59.000000Z\"}}', NULL, '2026-10-06 09:47:59', '2026-10-06 09:47:59'),
