(5750, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2783, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2783,\"component_id\":43,\"name\":\"Question\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Can a relative outside the immediate family sponsor a student?\",\"group\":\"3\",\"schema_group\":11,\"schema_instance\":1,\"position\":34,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-06T09:54:07.000000Z\",\"updated_at\":\"2026-10-06T09:54:07.000000Z\"}}', NULL, '2026-10-06 09:54:07', '2026-10-06 09:54:07'),
(5751, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2784, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2784,\"component_id\":43,\"name\":\"Answer\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Requirements vary by destination. Some accept extended family sponsors with additional evidence of relationship and intent, while others are stricter. We advise based on your specific destination.\",\"group\":\"3\",\"schema_group\":11,\"schema_instance\":1,\"position\":35,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-06T09:54:07.000000Z\",\"updated_at\":\"2026-10-06T09:54:07.000000Z\"}}', NULL, '2026-10-06 09:54:07', '2026-10-06 09:54:07'),
