(5987, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2922, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2922,\"component_id\":39,\"name\":\"Description\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Nothing is certified unless a document supports it. Where evidence is missing, we say so rather than soften the statement.\",\"group\":\"2\",\"schema_group\":2,\"schema_instance\":1,\"position\":3,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-07T06:12:47.000000Z\",\"updated_at\":\"2026-10-07T06:12:47.000000Z\"}}', NULL, '2026-10-07 06:12:47', '2026-10-07 06:12:47'),
(5988, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2923, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2923,\"component_id\":39,\"name\":\"Title\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Clarity about our role\",\"group\":\"2\",\"schema_group\":2,\"schema_instance\":2,\"position\":4,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-07T06:12:47.000000Z\",\"updated_at\":\"2026-10-07T06:12:47.000000Z\"}}', NULL, '2026-10-07 06:12:47', '2026-10-07 06:12:47'),
(5989, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2924, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2924,\"component_id\":39,\"name\":\"Description\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"We prepare and review documentation. We do not promise outcomes, and we correct any expectation that we can influence a decision.\",\"group\":\"2\",\"schema_group\":2,\"schema_instance\":2,\"position\":5,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-07T06:12:48.000000Z\",\"updated_at\":\"2026-10-07T06:12:48.000000Z\"}}', NULL, '2026-10-07 06:12:48', '2026-10-07 06:12:48'),
