(6148, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2995, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2995,\"component_id\":48,\"name\":\"Biography\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Kamrul Hasan founded the financial documentation practice at Mashiat International after twenty years in audit and assurance. He specialises in preparing defensible net worth statements and source-of-fund narratives for families sponsoring study abroad.\",\"group\":\"2\",\"schema_group\":4,\"schema_instance\":1,\"position\":11,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-07T10:56:36.000000Z\",\"updated_at\":\"2026-10-07T10:56:36.000000Z\"}}', NULL, '2026-10-07 10:56:36', '2026-10-07 10:56:36'),
(6149, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 2996, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":2996,\"component_id\":48,\"name\":\"Biography\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"He personally reviews every certification issued by the firm and works closely with sponsors to ensure the documentation they submit is internally consistent, verifiable and aligned with the financial requirements published by the relevant institution or immigration authority.\",\"group\":\"2\",\"schema_group\":4,\"schema_instance\":2,\"position\":12,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-07T10:56:36.000000Z\",\"updated_at\":\"2026-10-07T10:56:36.000000Z\"}}', NULL, '2026-10-07 10:56:36', '2026-10-07 10:56:36'),
