(6227, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 3036, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":3036,\"component_id\":50,\"name\":\"Section Title\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Students, sponsors and families at any stage\",\"group\":\"2\",\"schema_group\":1,\"schema_instance\":1,\"position\":1,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-07T11:45:06.000000Z\",\"updated_at\":\"2026-10-07T11:45:06.000000Z\"}}', NULL, '2026-10-07 11:45:06', '2026-10-07 11:45:06'),
(6228, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 3037, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":3037,\"component_id\":50,\"name\":\"Section Description\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Whether your deadline is weeks or a year away, the starting point is the same: an honest assessment of where the financial position stands today.\",\"group\":\"2\",\"schema_group\":1,\"schema_instance\":1,\"position\":2,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-07T11:45:07.000000Z\",\"updated_at\":\"2026-10-07T11:45:07.000000Z\"}}', NULL, '2026-10-07 11:45:07', '2026-10-07 11:45:07'),
