(6262, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 3060, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":3060,\"component_id\":51,\"name\":\"Title\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Unexplained funds invite questions\",\"group\":\"2\",\"schema_group\":3,\"schema_instance\":1,\"position\":5,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-07T12:02:00.000000Z\",\"updated_at\":\"2026-10-07T12:02:00.000000Z\"}}', NULL, '2026-10-07 12:02:00', '2026-10-07 12:02:00'),
(6263, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 3061, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":3061,\"component_id\":51,\"name\":\"Description\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"A balance that appears shortly before an application, without a documented origin, is the most common reason a financial file attracts further enquiry.\",\"group\":\"2\",\"schema_group\":3,\"schema_instance\":1,\"position\":6,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-07T12:02:01.000000Z\",\"updated_at\":\"2026-10-07T12:02:01.000000Z\"}}', NULL, '2026-10-07 12:02:01', '2026-10-07 12:02:01'),
(6264, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 3062, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":3062,\"component_id\":51,\"name\":\"Title\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Inconsistency undermines credibility\",\"group\":\"2\",\"schema_group\":3,\"schema_instance\":2,\"position\":7,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-07T12:02:01.000000Z\",\"updated_at\":\"2026-10-07T12:02:01.000000Z\"}}', NULL, '2026-10-07 12:02:01', '2026-10-07 12:02:01'),
(6265, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 3063, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":3063,\"component_id\":51,\"name\":\"Description\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"A name spelled two ways, a figure that does not reconcile, or a certificate dated outside the acceptable window can weaken an otherwise strong file.\",\"group\":\"2\",\"schema_group\":3,\"schema_instance\":2,\"position\":8,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-07T12:02:01.000000Z\",\"updated_at\":\"2026-10-07T12:02:01.000000Z\"}}', NULL, '2026-10-07 12:02:01', '2026-10-07 12:02:01'),
(6266, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 3064, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":3064,\"component_id\":51,\"name\":\"Title\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Timing cannot be recovered\",\"group\":\"2\",\"schema_group\":3,\"schema_instance\":3,\"position\":9,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-07T12:02:15.000000Z\",\"updated_at\":\"2026-10-07T12:02:15.000000Z\"}}', NULL, '2026-10-07 12:02:15', '2026-10-07 12:02:15'),
(6267, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 3065, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":3065,\"component_id\":51,\"name\":\"Description\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Maturity periods, transaction history and filing records accumulate over months. They cannot be assembled in the final weeks before a deadline.\",\"group\":\"2\",\"schema_group\":3,\"schema_instance\":3,\"position\":10,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-07T12:02:15.000000Z\",\"updated_at\":\"2026-10-07T12:02:15.000000Z\"}}', NULL, '2026-10-07 12:02:15', '2026-10-07 12:02:15'),
