(6344, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 3094, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":3094,\"component_id\":2,\"name\":\"Section Title\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"A professional firm, not an agency\",\"group\":\"2\",\"schema_group\":1,\"schema_instance\":1,\"position\":1,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-07T13:08:11.000000Z\",\"updated_at\":\"2026-10-07T13:08:11.000000Z\"}}', NULL, '2026-10-07 13:08:11', '2026-10-07 13:08:11'),
(6345, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 3095, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":3095,\"component_id\":2,\"name\":\"Paragraph\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Mashiat International was established to bring professional accounting standards to an area families usually navigate alone: proving they can fund an international education.\",\"group\":\"2\",\"schema_group\":3,\"schema_instance\":1,\"position\":2,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-07T13:08:11.000000Z\",\"updated_at\":\"2026-10-07T13:08:11.000000Z\"}}', NULL, '2026-10-07 13:08:11', '2026-10-07 13:08:11'),
(6346, 'componentfield', 'created', 'App\\Models\\ComponentField', 'created', 3096, 'App\\Models\\User', 1, '{\"attributes\":{\"id\":3096,\"component_id\":2,\"name\":\"Paragraph\",\"type\":\"text\",\"relationship_type\":null,\"related_component\":null,\"display_column\":null,\"static_options\":null,\"help_text\":null,\"is_required\":0,\"value\":\"Our consultants come from audit, banking, taxation and corporate compliance backgrounds. That means a net worth statement is built from evidence, a sponsor\'s income is reconciled against filed returns, and every figure in a file can be traced to a document behind it.\",\"group\":\"2\",\"schema_group\":3,\"schema_instance\":2,\"position\":3,\"show_in_table\":1,\"colspan\":6,\"page_id\":null,\"created_at\":\"2026-10-07T13:08:11.000000Z\",\"updated_at\":\"2026-10-07T13:08:11.000000Z\"}}', NULL, '2026-10-07 13:08:11', '2026-10-07 13:08:11'),
