(3035, 50, 'Section Label', 'text', NULL, NULL, NULL, NULL, NULL, 0, 'Who this is for', '2', 1, 1, 0, 1, 6, NULL, '2026-10-07 11:45:06', '2026-10-07 11:45:06'),
(3036, 50, 'Section Title', 'text', NULL, NULL, NULL, NULL, NULL, 0, 'Students, sponsors and families at any stage', '2', 1, 1, 1, 1, 6, NULL, '2026-10-07 11:45:06', '2026-10-07 11:45:06'),
(3037, 50, 'Section Description', 'text', NULL, NULL, NULL, NULL, NULL, 0, 'Whether your deadline is weeks or a year away, the starting point is the same: an honest assessment of where the financial position stands today.', '2', 1, 1, 2, 1, 6, NULL, '2026-10-07 11:45:07', '2026-10-07 11:45:07'),
(3038, 50, 'Title', 'text', NULL, NULL, NULL, NULL, NULL, 0, 'Students with an offer in hand', '2', 2, 1, 3, 1, 6, NULL, '2026-10-07 11:45:07', '2026-10-07 11:45:07'),
(3039, 50, 'Description', 'text', NULL, NULL, NULL, NULL, NULL, 0, 'You have an admission or conditional offer and need the financial evidence organised before the visa application window opens.', '2', 2, 1, 4, 1, 6, NULL, '2026-10-07 11:45:07', '2026-10-07 11:45:07'),
(3040, 50, 'Icon', 'text', NULL, NULL, NULL, NULL, NULL, 0, '<i class=\"fa-solid fa-graduation-cap\"></i>', '2', 2, 1, 5, 1, 6, NULL, '2026-10-07 11:45:07', '2026-10-07 11:45:07'),
(3041, 50, 'Title', 'text', NULL, NULL, NULL, NULL, NULL, 0, 'Parents and family sponsors', '2', 2, 2, 6, 1, 6, NULL, '2026-10-07 11:45:07', '2026-10-07 11:45:07'),
(3042, 50, 'Description', 'text', NULL, NULL, NULL, NULL, NULL, 0, 'You are funding the study and need your income, assets and source of funds documented in a form an assessing officer can verify', '2', 2, 2, 7, 1, 6, NULL, '2026-10-07 11:45:07', '2026-10-07 11:45:07'),
(3043, 50, 'Icon', 'text', NULL, NULL, NULL, NULL, NULL, 0, '<i class=\"fa-solid fa-user\"></i>', '2', 2, 2, 8, 1, 6, NULL, '2026-10-07 11:45:07', '2026-10-07 11:45:07'),
(3044, 50, 'Title', 'text', NULL, NULL, NULL, NULL, NULL, 0, 'Self-employed and business sponsors', '2', 2, 3, 9, 1, 6, NULL, '2026-10-07 11:45:07', '2026-10-07 11:45:07'),
(3045, 50, 'Description', 'text', NULL, NULL, NULL, NULL, NULL, 0, 'Your income comes from a business, so trade licences, company records, filed returns and accounts must reconcile with your bank activity.', '2', 2, 3, 10, 1, 6, NULL, '2026-10-07 11:45:07', '2026-10-07 11:45:07'),
