(3055, 51, 'Section Label', 'text', NULL, NULL, NULL, NULL, NULL, 0, 'Why it matters', '2', 1, 1, 0, 1, 6, NULL, '2026-10-07 12:02:00', '2026-10-07 12:02:00'),
(3056, 51, 'Section Title', 'text', NULL, NULL, NULL, NULL, NULL, 0, 'Why proper financial documentation matters', '2', 1, 1, 1, 1, 6, NULL, '2026-10-07 12:02:00', '2026-10-07 12:02:00'),
(3057, 51, 'Section Description', 'text', NULL, NULL, NULL, NULL, NULL, 0, 'Applications are rarely refused because a family cannot afford the course. They are questioned because the paperwork does not explain the money clearly.', '2', 1, 1, 2, 1, 6, NULL, '2026-10-07 12:02:00', '2026-10-07 12:02:00'),
(3058, 51, 'Button Text', 'text', NULL, NULL, NULL, NULL, NULL, 0, 'Start with an assessment', '2', 2, 1, 3, 1, 6, NULL, '2026-10-07 12:02:00', '2026-10-07 12:02:00'),
(3059, 51, 'Button URL', 'text', NULL, NULL, NULL, NULL, NULL, 0, '/contact', '2', 2, 1, 4, 1, 6, NULL, '2026-10-07 12:02:00', '2026-10-07 12:02:00'),
(3060, 51, 'Title', 'text', NULL, NULL, NULL, NULL, NULL, 0, 'Unexplained funds invite questions', '2', 3, 1, 5, 1, 6, NULL, '2026-10-07 12:02:00', '2026-10-07 12:02:00'),
(3061, 51, 'Description', 'text', NULL, NULL, NULL, NULL, NULL, 0, 'A balance that appears shortly before an application, without a documented origin, is the most common reason a financial file attracts further enquiry.', '2', 3, 1, 6, 1, 6, NULL, '2026-10-07 12:02:01', '2026-10-07 12:02:01'),
(3062, 51, 'Title', 'text', NULL, NULL, NULL, NULL, NULL, 0, 'Inconsistency undermines credibility', '2', 3, 2, 7, 1, 6, NULL, '2026-10-07 12:02:01', '2026-10-07 12:02:01'),
(3063, 51, 'Description', 'text', NULL, NULL, NULL, NULL, NULL, 0, 'A name spelled two ways, a figure that does not reconcile, or a certificate dated outside the acceptable window can weaken an otherwise strong file.', '2', 3, 2, 8, 1, 6, NULL, '2026-10-07 12:02:01', '2026-10-07 12:02:01'),
(3064, 51, 'Title', 'text', NULL, NULL, NULL, NULL, NULL, 0, 'Timing cannot be recovered', '2', 3, 3, 9, 1, 6, NULL, '2026-10-07 12:02:15', '2026-10-07 12:02:15'),
(3065, 51, 'Description', 'text', NULL, NULL, NULL, NULL, NULL, 0, 'Maturity periods, transaction history and filing records accumulate over months. They cannot be assembled in the final weeks before a deadline.', '2', 3, 3, 10, 1, 6, NULL, '2026-10-07 12:02:15', '2026-10-07 12:02:15'),
(3066, 52, 'Section Label', 'text', NULL, NULL, NULL, NULL, NULL, 0, NULL, '1', 1, 1, 0, 1, 6, NULL, '2026-10-07 12:17:01', '2026-10-07 12:18:37'),
