INSERT INTO `pages` (`id`, `name`, `permalink`, `description`, `page_text_content`, `status`, `is_breadcrumb`, `image`, `seo_title`, `seo_description`, `seo_image`, `seo_index`, `header_component`, `header_component_position`, `footer_component`, `created_at`, `updated_at`) VALUES
(1, 'Home', '/', '<p><br></p>', '<p><br></p>', '1', 0, NULL, NULL, NULL, NULL, 'noindex', 'header', NULL, 'footer', '2026-03-09 09:39:52', '2026-03-09 09:41:04'),
(3, 'about', 'about', '<p>&lt;p class=\"mb-4 text-[13px] font-semibold text-status\"&gt;<span style=\"color: rgb(231, 214, 172);font-size: 13px;background-color: rgb(9, 26, 46)\">About us</span>&lt;/p&gt;<br>&lt;h1 class=\"text-[31px] font-bold leading-[1.1] text-white min-[380px]:text-[34px] sm:text-[46px] lg:text-[54px]\"&gt;A Dhaka practice built around financial evidence&lt;/h1&gt;<br>&lt;p class=\"mt-5 max-w-2xl text-[16px] leading-relaxed text-white/75 sm:text-lg\"&gt;Mashiat International combines chartered accountancy, taxation, corporate compliance and legal support in one firm ??? so the documents behind a study abroad application, a licence renewal or a tax filing all reconcile.&lt;/p&gt;</p>', '<p><br></p>', '1', 1, NULL, NULL, NULL, NULL, 'noindex', 'header', 'fix', 'footer', '2026-03-13 05:57:09', '2026-10-11 05:50:11'),
(12, 'service', 'service', '<p>&lt;p class=\"mb-4 text-[13px] font-semibold text-status\"&gt;Services directory&lt;/p&gt;<br>&lt;h1 class=\"text-[31px] font-bold leading-[1.1] text-white min-[380px]:text-[34px] sm:text-[46px] lg:text-[54px]\"&gt;Professional services across finance, tax, corporate and compliance&lt;/h1&gt;<br>&lt;p class=\"mt-5 max-w-2xl text-[16px] leading-relaxed text-white/75 sm:text-lg\"&gt;Twenty services delivered by one practice ??? from student visa financial documentation to incorporation, licensing, valuation and legal support.&lt;/p&gt;</p>', '<p><br></p>', '1', 1, NULL, NULL, NULL, NULL, 'noindex', 'header', 'fix', 'footer', '2026-10-06 05:46:59', '2026-10-11 05:28:40'),
(14, 'Our Team', 'our-team', '<p>&lt;p class=\"mb-4 text-[13px] font-semibold text-status\"&gt;Our team&lt;/p&gt;<br>&lt;h1 class=\"text-[31px] font-bold leading-[1.1] text-white min-[380px]:text-[34px] sm:text-[46px] lg:text-[54px]\"&gt;Consultants who sign their work&lt;/h1&gt;<br>&lt;p class=\"mt-5 max-w-2xl text-[16px] leading-relaxed text-white/75 sm:text-lg\"&gt;Chartered Accountants, tax practitioners, corporate specialists and advocates. Every engagement is led by a named professional who remains your point of contact throughout.&lt;/p&gt;</p>', '<p><br></p>', '1', 1, NULL, NULL, NULL, NULL, 'noindex', 'header', 'fix', 'footer', '2026-10-07 10:59:41', '2026-10-11 06:05:10'),
(15, 'Student Visa', 'student-visa', '<p>&lt;p class=\"mb-4 text-[13px] font-semibold text-status\"&gt;Student visa financial documentation&lt;/p&gt;<br>&lt;h1 class=\"text-[31px] font-bold leading-[1.1] text-white min-[380px]:text-[34px] sm:text-[46px] lg:text-[54px]\"&gt;Financial documentation for your study abroad journey&lt;/h1&gt;<br>&lt;p class=\"mt-5 max-w-2xl text-[16px] leading-relaxed text-white/75 sm:text-lg\"&gt;Assessment, sponsor documentation, source-of-fund evidence, certified net worth reporting and a final application-ready review ??? prepared by qualified professionals in one practice.&lt;/p&gt;</p>', '<p><br></p>', '1', 1, NULL, NULL, NULL, NULL, 'noindex', 'header', 'fix', 'footer', '2026-10-07 11:24:07', '2026-10-11 06:04:15'),
(17, 'contact', 'contact', '<p>&lt;p class=\"mb-4 text-[13px] font-semibold text-status\"&gt;Contact&lt;/p&gt;<br>&lt;h1 class=\"text-[31px] font-bold leading-[1.1] text-white min-[380px]:text-[34px] sm:text-[46px] lg:text-[54px]\"&gt;Book a consultation with our team&lt;/h1&gt;<br>&lt;p class=\"mt-5 max-w-2xl text-[16px] leading-relaxed text-white/75 sm:text-lg\"&gt;Call, message on WhatsApp, or send the consultation form below. A consultant will confirm a time and tell you what to prepare.&lt;/p&gt;</p>', '<p><br></p>', '1', 1, NULL, NULL, NULL, NULL, 'noindex', 'header', 'fix', 'footer', '2026-10-07 12:27:37', '2026-10-11 06:06:47');
